// (card colour; the 16 set pieces are the set's "name colour"), typing_flare.
// Exports `items` in the shared catalog data contract (see the Market 2.0 plan):
//   { sku, category, rarity, price_descoin, set_key, effect_key, asset_url, preview_url,
//     theme_key, badge_icon, sort_order, tags, name: {7 locales}, description: {7 locales} }
// Rendering: every effect_key is drawn by frontend/src/styles/shop2-c2.css
//   chat_bubble   .cosmetic-chat-bubble.bubble-<effect_key>
//   name_effect   .cosmetic-name-effect.effect-<effect_key>
//   profile_color lib/shop2ProfileColors.js palette + .pc-<effect_key> art (via lib/profileColors.js)
//   typing_flare  .cosmetic-typing-flare.typing-<effect_key> + .typing-shell-<effect_key>
// Names and descriptions follow the order tr, en, de, es, fr, pt-BR, ru.

const LOCALES = ["tr", "en", "de", "es", "fr", "pt-BR", "ru"];
const loc = (arr, sku, field) => {
  if (!Array.isArray(arr) || arr.length !== LOCALES.length) throw new Error(`${sku}: ${field} needs ${LOCALES.length} locales`);
  return Object.fromEntries(LOCALES.map((l, i) => [l, arr[i]]));
};

