const SORT_BASE = { chat_bubble: 23000, name_effect: 24000, profile_color: 25000, typing_flare: 26000 };

function make(category, slug, { rarity, price, setKey = null, effectKey, names, desc, tags = [], index }) {
  const sku = `s2-${category}-${slug}`;
  const allTags = ["shop2", "c2", ...tags];
  if (setKey) allTags.push("set", `set:${setKey}`);
  return {
    sku,
    category,
    rarity,
    price_descoin: price,
    set_key: setKey,
    effect_key: effectKey,
    asset_url: null,
    preview_url: null,
    theme_key: null,
    badge_icon: null,
    sort_order: SORT_BASE[category] + (setKey ? 0 : 500) + index,
    tags: [...new Set(allTags)],
    name: loc(names, sku, "name"),
    description: loc(desc, sku, "description"),
  };
}

function build() {
  const out = [];
  SET_BUBBLES.forEach(([setKey, price, names, desc], i) =>
    out.push(make("chat_bubble", `set-${setKey}`, { rarity: "epic", price, setKey, effectKey: `s2-set-${setKey}`, names, desc, tags: ["animated"], index: i })));
  BUBBLES.forEach(([slug, rarity, price, anim, names, desc, tags], i) =>
    out.push(make("chat_bubble", slug, { rarity, price, effectKey: `s2-${slug}`, names, desc, tags: [...(tags || []), ...(anim ? ["animated"] : [])], index: i })));
  NAME_EFFECTS.forEach(([slug, rarity, price, anim, names, desc], i) =>
    out.push(make("name_effect", slug, { rarity, price, effectKey: `s2-${slug}`, names, desc, tags: anim ? ["animated"] : [], index: i })));
  SET_COLORS.forEach(([setKey, price, names, desc], i) =>
    out.push(make("profile_color", `set-${setKey}`, { rarity: "rare", price, setKey, effectKey: `s2-set-${setKey}`, names, desc, tags: ["name-colour"], index: i })));
  CARD_COLORS.forEach(([slug, rarity, price, names, desc], i) =>
    out.push(make("profile_color", slug, { rarity, price, effectKey: `s2-pc-${slug}`, names, desc, index: i })));
  TYPING_FLARES.forEach(([slug, rarity, price, names, desc], i) =>
    out.push(make("typing_flare", slug, { rarity, price, effectKey: `s2-${slug}`, names, desc, tags: ["animated"], index: i })));
  const seen = new Set();
  for (const it of out) {
    if (seen.has(it.sku)) throw new Error(`duplicate sku ${it.sku}`);
    seen.add(it.sku);
  }
  for (const k of SET_KEYS) {
    if (!out.some((it) => it.set_key === k && it.category === "chat_bubble")) throw new Error(`set ${k}: no chat bubble`);
    if (!out.some((it) => it.set_key === k && it.category === "profile_color")) throw new Error(`set ${k}: no name colour`);
  }
  return out;
}

const items = build();

module.exports = { items, LOCALES, SET_KEYS };
